/// <summary>
/// Count control center, by store (View: By store): one row per store journal - all the blind
/// counts of a store going into one D365FO counting journal (Count types: One journal per store).
/// Bins counted twice across those counts are decided here (Keep selected, Add together, Reject
/// both); the store journal posts tonight once none is left, unless it is on hold. The tiles open
/// this form again, filtered by their query. By count is the earlier one-row-per-count form
/// (HSMobileOpsCountControlCenterByCount). Rules: HSMobileOpsCountStoreJournalEngine.
/// </summary>
[Form]
public class HSMobileOpsCountControlCenter extends FormRun
{
    QueryBuildRange countTypeRange;
    QueryBuildDataSource hazardSource;
}

public void init()
{
    // Figures that change with time alone (counters not ended), and journals posted in D365FO.
    HSMobileOpsCountStoreJournalEngine::refreshOpen();
    HSMobileOpsCountStoreJournalEngine::ensureHazardStores();
    super();
    CountTypeFilter.selection(HSMobileOpsCountMasterType::Blind);
    FromDateFilter.dateValue(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()) - 6);
}

/// <summary>
/// The selected count's Requested items number after a row is added or removed.
/// </summary>
public void refreshRequestedCount()
{
    BlindCount_ds.reread();
    BlindCount_ds.refresh();
}

/// <summary>
/// A section's heading with its summary after it, in full (a summary field would be cut short).
/// </summary>
public void sectionCaption(FormTabPageControl _page, str _title, str _summary)
{
    _page.caption(_summary ? strFmt('%1 - %2', _title, _summary) : _title);
}

/// <summary>
/// The FastTab summaries and the buttons for the selected store journal.
/// </summary>
public void updateSelection()
{
    HSMobileOpsCountStoreJournal storeJournal = HSMobileOpsCountStoreJournal;
    HSMobileOpsCountMaster       master;
    HSMobileOpsCountDecisionLog  logRow;
    str                          counts;
    boolean                      open = storeJournal.RecId && !storeJournal.Posted;

    element.sectionCaption(CountedTwicePage, 'Counted twice', storeJournal.RecId ? strFmt('%1 %2 · %3 · %4 bin(s) to decide', storeJournal.InventLocationId, storeJournal.StoreName,
        storeJournal.JournalId ? storeJournal.JournalId : 'no journal yet', storeJournal.CountedTwiceCount) : '');
    while select MasterId from master
        order by MasterId
        where (master.StoreJournalRecId == storeJournal.RecId
            && master.Status            != HSMobileOpsCountMasterStatus::Cancelled)
           || (storeJournal.RecId
            && master.InventLocationId == storeJournal.InventLocationId
            && master.MasterType       == HSMobileOpsCountMasterType::Hazard
            && master.Status           == HSMobileOpsCountMasterStatus::Open)
    {
        counts += (counts ? ' · ' : '') + master.MasterId;
    }
    element.sectionCaption(BlindCountsPage, 'Counts', counts);
    element.sectionCaption(CountedLinesPage, 'Counted lines', strFmt('%1 lines · %2 with variance', storeJournal.LineCount, storeJournal.VarianceLineCount));
    element.sectionCaption(CountersPage, 'Counters', strFmt('%1 counter(s) · %2', storeJournal.CounterCount,
        storeJournal.CountingNow ? strFmt('%1 counting now', storeJournal.CountingNow) : 'all ended'));
    select count(RecId) from logRow where logRow.StoreJournalRecId == storeJournal.RecId;
    element.sectionCaption(DecisionLogPage, 'Decision log', logRow.RecId ? strFmt('%1 decision(s)', logRow.RecId) : 'No decisions yet');

    OpenJournalButton.enabled(storeJournal.JournalId != '');
    PostNowButton.enabled(open && !storeJournal.OnHold && storeJournal.JournalId != '');
    HoldButton.enabled(open && !storeJournal.OnHold);
    ReleaseButton.enabled(open && storeJournal.OnHold);
    RefreshButton.enabled(open);
}

/// <summary>
/// Count type: store journals holding a count of that type (Blind - a store journal is only
/// ever of blind counts). Sorted by store.
/// </summary>
public void init()
{
    QueryBuildDataSource typeSource;

    super();
    typeSource = this.queryBuildDataSource().addDataSource(tableNum(HSMobileOpsCountMaster));
    typeSource.joinMode(JoinMode::ExistsJoin);
    typeSource.relations(false);
    typeSource.addLink(fieldNum(HSMobileOpsCountStoreJournal, RecId), fieldNum(HSMobileOpsCountMaster, StoreJournalRecId));
    countTypeRange = typeSource.addRange(fieldNum(HSMobileOpsCountMaster, MasterType));
    // Hazard counts have no store journal: a store is listed by its open hazard counts.
    hazardSource = this.queryBuildDataSource().addDataSource(tableNum(HSMobileOpsCountMaster));
    hazardSource.joinMode(JoinMode::ExistsJoin);
    hazardSource.relations(false);
    hazardSource.addLink(fieldNum(HSMobileOpsCountStoreJournal, InventLocationId), fieldNum(HSMobileOpsCountMaster, InventLocationId));
    hazardSource.addRange(fieldNum(HSMobileOpsCountMaster, MasterType)).value(SysQuery::value(HSMobileOpsCountMasterType::Hazard));
    hazardSource.addRange(fieldNum(HSMobileOpsCountMaster, Status)).value(SysQuery::value(HSMobileOpsCountMasterStatus::Open));
    hazardSource.enabled(false);
    this.queryBuildDataSource().addSortField(fieldNum(HSMobileOpsCountStoreJournal, InventLocationId));
}

/// <summary>
/// The supervisor's stores (Count stores), and the filters above the grid.
/// </summary>
public void executeQuery()
{
    QueryBuildDataSource source = this.queryBuildDataSource();
    date                 fromDate = FromDateFilter.dateValue();
    boolean              hazard;

    SysQuery::findOrCreateRange(source, fieldNum(HSMobileOpsCountStoreJournal, InventLocationId)).value(HSMobileOpsCountStoreJournalEngine::myStores());
    hazard = CountTypeFilter.selection() == HSMobileOpsCountMasterType::Hazard;
    // An open hazard count is listed whatever its date; its store's row may have no counts yet.
    SysQuery::findOrCreateRange(source, fieldNum(HSMobileOpsCountStoreJournal, LastCountUtc)).value(fromDate && !hazard
        ? SysQuery::range(DateTimeUtil::newDateTime(fromDate, 0, DateTimeUtil::getUserPreferredTimeZone()), DateTimeUtil::maxValue()) : '');
    SysQuery::findOrCreateRange(source, fieldNum(HSMobileOpsCountStoreJournal, Posted)).value(hazard ? SysQuery::value(NoYes::No) : '');
    countTypeRange.value(SysQuery::value(CountTypeFilter.selection()));
    countTypeRange.dataSource().enabled(!hazard);
    hazardSource.enabled(hazard);
    super();
}

public int active()
{
    int ret = super();

    TwiceLine_ds.executeQuery();
    BlindCount_ds.executeQuery();
    CountedLine_ds.executeQuery();
    Counter_ds.executeQuery();
    DecisionLog_ds.executeQuery();
    element.updateSelection();
    return ret;
}

/// <summary>
/// The store journal's bins counted twice, the counts of each together.
/// </summary>
public void init()
{
    super();
    this.queryBuildDataSource().clearDynalinks();
    this.queryBuildDataSource().addDynalink(fieldNum(HSMobileOpsCountStageLine, StoreJournalRecId), HSMobileOpsCountStoreJournal, fieldNum(HSMobileOpsCountStoreJournal, RecId));
    this.queryBuildDataSource().addRange(fieldNum(HSMobileOpsCountStageLine, IsDuplicate)).value(SysQuery::value(NoYes::Yes));
    this.queryBuildDataSource().addSortField(fieldNum(HSMobileOpsCountStageLine, DuplicateKey));
    this.queryBuildDataSource().addSortField(fieldNum(HSMobileOpsCountStageLine, CountedUtc));
}

public void init()
{
    super();
    this.queryBuildDataSource().clearDynalinks();
    this.queryBuildDataSource().addSortField(fieldNum(HSMobileOpsCountMaster, MasterId));
}

/// <summary>
/// The store journal's blind counts and the store's open hazard counts (user, 25 Nov 2026:
/// hazard counts are shown by store too; they still make their own journal).
/// </summary>
public void executeQuery()
{
    HSMobileOpsCountStoreJournal storeJournal = HSMobileOpsCountStoreJournal;

    SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(HSMobileOpsCountMaster, RecId)).value(strFmt(
        '((%1 == %2) || ((%3 == "%4") && (%5 == %6) && (%7 == %8)))',
        fieldStr(HSMobileOpsCountMaster, StoreJournalRecId), storeJournal.RecId ? storeJournal.RecId : -1,
        fieldStr(HSMobileOpsCountMaster, InventLocationId), storeJournal.InventLocationId ? storeJournal.InventLocationId : '-',
        fieldStr(HSMobileOpsCountMaster, MasterType), enum2int(HSMobileOpsCountMasterType::Hazard),
        fieldStr(HSMobileOpsCountMaster, Status), enum2int(HSMobileOpsCountMasterStatus::Open)));
    super();
}

/// <summary>
/// Requested items of the selected count; they can be changed while it is open.
/// </summary>
public int active()
{
    int     ret = super();
    boolean open = BlindCount.RecId && BlindCount.Status == HSMobileOpsCountMasterStatus::Open
                && (BlindCount.MasterType == HSMobileOpsCountMasterType::Blind
                 || BlindCount.MasterType == HSMobileOpsCountMasterType::Hazard);

    RequestedItem_ds.executeQuery();
    RequestedItem_ds.allowCreate(open);
    RequestedItem_ds.allowEdit(open);
    RequestedItem_ds.allowDelete(open);
    element.sectionCaption(RequestedItemsPage, 'Requested items', BlindCount.MasterId);
    return ret;
}

public void init()
{
    super();
    this.queryBuildDataSource().clearDynalinks();
    this.queryBuildDataSource().addDynalink(fieldNum(HSMobileOpsCountItem, MasterRecId), BlindCount, fieldNum(HSMobileOpsCountMaster, RecId));
    this.queryBuildDataSource().addSortField(fieldNum(HSMobileOpsCountItem, LineNum));
}

public void initValue()
{
    super();
    RequestedItem.MasterRecId = BlindCount.RecId;
}

public void write()
{
    super();
    element.refreshRequestedCount();
}

public void delete()
{
    super();
    element.refreshRequestedCount();
}

public void init()
{
    super();
    this.queryBuildDataSource().clearDynalinks();
    this.queryBuildDataSource().addDynalink(fieldNum(HSMobileOpsCountStageLine, StoreJournalRecId), HSMobileOpsCountStoreJournal, fieldNum(HSMobileOpsCountStoreJournal, RecId));
}

public void init()
{
    super();
    this.queryBuildDataSource().clearDynalinks();
    this.queryBuildDataSource().addDynalink(fieldNum(HSMobileOpsCountStage, StoreJournalRecId), HSMobileOpsCountStoreJournal, fieldNum(HSMobileOpsCountStoreJournal, RecId));
}

public void init()
{
    super();
    this.queryBuildDataSource().clearDynalinks();
    this.queryBuildDataSource().addDynalink(fieldNum(HSMobileOpsCountDecisionLog, StoreJournalRecId), HSMobileOpsCountStoreJournal, fieldNum(HSMobileOpsCountStoreJournal, RecId));
}

public boolean modified()
{
    boolean ret = super();

    HSMobileOpsCountStoreJournal_ds.executeQuery();
    return ret;
}

public boolean modified()
{
    boolean ret = super();

    HSMobileOpsCountStoreJournal_ds.executeQuery();
    return ret;
}
